 '4-2-3-1':{blue:[[70,210,'1'],[170,66,'2'],[140,154,'4'],[140,266,'5'],[170,354,'3'],[260,158,'6'],[260,262,'8'],[380,75,'7'],[390,210,'10'],[380,345,'11'],[500,210,'9']],red:[[620,210,'1'],[530,66,'2'],[560,154,'4'],[560,266,'5'],[530,354,'3'],[460,158,'6'],[460,262,'8'],[370,75,'7'],[360,210,'10'],[370,345,'11'],[290,210,'9']]},
