document.addEventListener('toggle',e=>{const card=e.target;if(!card?.matches?.('[data-analysis-card]'))return;const id=card.dataset.analysisId;if(card.open){if(!state.expandedAnalyses.includes(id))state.expandedAnalyses.push(id);}else state.expandedAnalyses=state.expandedAnalyses.filter(x=>x!==id);},true);
document.addEventListener('click',e=>{
 const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();const v=nav.dataset.nav;if(v==='academy')state.academySearch='';setView(v);return;}
 const action=e.target.closest('[data-action]');if(action){e.preventDefault();onClickAction(action);return;}
 const task=e.target.closest('[data-task]');if(task){const id=task.dataset.task;const checked=task.checked;if(checked&&!store.tasks.includes(id))store.tasks.push(id);if(!checked)store.tasks=store.tasks.filter(x=>x!==id);persist();if(state.view==='dashboard')renderApp();return;}
});
document.addEventListener('input',e=>{
 const practiceField=e.target.closest('[data-practice-response]');if(practiceField){const id=practiceField.dataset.practiceResponse;store.practiceSubmissions=store.practiceSubmissions||{};store.practiceSubmissions[id]={...(store.practiceSubmissions[id]||{}),response:practiceField.value,submitted:false};persist();return;}
 const analysisSearch=e.target.closest('[data-analysis-search]');if(analysisSearch){state.analysisSearch=analysisSearch.value.trim();const q=state.analysisSearch.toLocaleLowerCase('pl');let shown=0;document.querySelectorAll('[data-analysis-card]').forEach(card=>{const match=(card.dataset.searchText||'').toLocaleLowerCase('pl').includes(q);card.hidden=!match;if(match)shown++;});const count=document.querySelector('.analysis-library-tools .muted');if(count)count.textContent=`${shown} z ${analyses.length} studiów`;return;}
 const coachResponse=e.target.closest('[data-coach-response]');if(coachResponse){const id=coachResponse.dataset.coachResponse;store.coachQuizzes=store.coachQuizzes||{};store.coachQuizzes[id]={...(store.coachQuizzes[id]||{}),response:coachResponse.value,submitted:false};persist();return;}
 const boardReasoning=e.target.closest('#board-challenge-reasoning');if(boardReasoning&&state.boardChallenge){const id=state.boardChallenge.analysisId;store.coachQuizzes=store.coachQuizzes||{};store.coachQuizzes[id]={...(store.coachQuizzes[id]||{}),boardDraft:boardReasoning.value};persist();return;}
 const analysisField=e.target.closest('[data-analysis-field]');if(analysisField){const id=analysisField.dataset.analysisId;const key=analysisField.dataset.analysisField;store.analysisWork=store.analysisWork||{};store.analysisWork[id]={...(store.analysisWork[id]||{}),[key]:analysisField.value,submitted:false};persist();return;}
 if(e.target.id==='academy-search'){state.academySearch=e.target.value;const pos=e.target.selectionStart;renderApp();const next=document.getElementById('academy-search');if(next){next.focus();next.setSelectionRange(pos,pos);}return;}
});
document.addEventListener('change',e=>{
 if(e.target.matches('[data-practice-score]')){const id=e.target.dataset.lessonId;const key=e.target.dataset.practiceScore;const current=store.practiceSubmissions[id]||{};current.scores={...(current.scores||{}),[key]:Number(e.target.value)};current.submitted=false;store.practiceSubmissions[id]=current;persist();return;}
 if(e.target.matches('input[name="lesson-quiz"]')){const l=state.activeLesson;state.lessonAnswers[l]=Number(e.target.value);document.querySelectorAll('.quiz-option').forEach(el=>el.classList.remove('selected'));e.target.closest('.quiz-option')?.classList.add('selected');return;}
 if(e.target.matches('[data-scout-check]')){state.scoutChecks[e.target.dataset.scoutCheck]=e.target.checked;const checked=Object.values(state.scoutChecks).filter(Boolean).length;const bar=document.querySelector('.scout-grid .progress-bar span');if(bar)bar.style.width=(checked/6*100)+'%';const label=document.querySelector('.scout-grid .progress-bar')?.nextElementSibling;if(label)label.textContent=`${checked} z 6 obszarów sprawdzonych`;return;}
});
document.addEventListener('keydown',e=>{
 if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('global-search')?.focus();}
 if(e.key==='Enter'&&e.target.id==='global-search'){e.preventDefault();const q=e.target.value.trim();if(q){state.searchQuery=q;state.view='search';state.activeLesson=null;renderApp();}}
 if(e.key==='Escape'){document.getElementById('sidebar')?.classList.remove('open');}
});
document.getElementById('mobile-menu')?.addEventListener('click',()=>{const side=document.getElementById('sidebar');side.classList.toggle('open');});
document.getElementById('sidebar-overlay')?.addEventListener('click',()=>document.getElementById('sidebar')?.classList.remove('open'));
// Clicks on the SVG add players or build a two-point arrow; pointer dragging moves existing markers.
document.addEventListener('click',e=>{
 const svg=e.target.closest('#tactic-pitch');if(!svg)return;
 const clickedToken=e.target.closest('[data-token-id]');if(clickedToken&&state.boardMode!=='arrow')return;
 const rect=svg.getBoundingClientRect();const token=clickedToken?state.boardTokens.find(t=>t.id===Number(clickedToken.dataset.tokenId)):null;const x=token?token.x:Math.max(16,Math.min(684,(e.clientX-rect.left)/rect.width*700));const y=token?token.y:Math.max(16,Math.min(404,(e.clientY-rect.top)/rect.height*420));
 if(state.boardMode==='arrow'){
  if(!state.boardPendingArrow)state.boardPendingArrow={x,y};else{state.boardArrows.push({x1:state.boardPendingArrow.x,y1:state.boardPendingArrow.y,x2:x,y2:y});state.boardPendingArrow=null;}
 }else{state.boardTokens.push({id:state.nextTokenId++,team:state.boardTeam,x,y,label:String(state.boardTokens.filter(t=>t.team===state.boardTeam).length+1)});}
 persistBoardDraft();renderApp();
});
document.addEventListener('pointerdown',e=>{const token=e.target.closest('[data-token-id]');if(!token)return;const svg=token.closest('#tactic-pitch');if(!svg)return;e.preventDefault();e.stopPropagation();state.dragToken=Number(token.dataset.tokenId);try{svg.setPointerCapture(e.pointerId);}catch{} });
document.addEventListener('pointermove',e=>{if(state.dragToken===null)return;const svg=document.getElementById('tactic-pitch');if(!svg)return;const rect=svg.getBoundingClientRect();const x=Math.max(16,Math.min(684,(e.clientX-rect.left)/rect.width*700));const y=Math.max(16,Math.min(404,(e.clientY-rect.top)/rect.height*420));const token=state.boardTokens.find(t=>t.id===state.dragToken);if(token){token.x=x;token.y=y;const g=svg.querySelector(`[data-token-id="${state.dragToken}"]`);if(g){g.querySelector('circle').setAttribute('cx',x);g.querySelector('circle').setAttribute('cy',y);g.querySelector('text').setAttribute('x',x);g.querySelector('text').setAttribute('y',y+3.8);}}});
document.addEventListener('pointerup',()=>{if(state.dragToken!==null){state.dragToken=null;persistBoardDraft();}});
// Expose a narrow bridge for authenticated cloud sync; auth secrets never belong in this file.
window.SzkolaApp={store,renderApp,persist,storeKey:STORE_KEY,defaultStore:()=>clone(defaultStore),replaceStore(next){for(const k of Object.keys(store))delete store[k];Object.assign(store,clone(next));localStorage.setItem(STORE_KEY,JSON.stringify(store));if(store.boardDraft)restoreBoardDraft();renderApp();}};
// Restore the trainer's saved board across refreshes; otherwise provide a useful starting formation.
if(!restoreBoardDraft())presetForm('4-3-3');
renderApp();

